import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const __dirname = dirname(fileURLToPath(import.meta.url));
let failures = [];

// 1. Check windows.mjs: win32 should use titleBarStyle: "hidden" + titleBarOverlay
const windowsMjs = readFileSync(join(__dirname, "desktop/lib/windows.mjs"), "utf-8");

// Must have TITLE_BAR_OVERLAY constant with correct values
if (!windowsMjs.includes("TITLE_BAR_OVERLAY")) {
  failures.push("Missing TITLE_BAR_OVERLAY constant in windows.mjs");
} else if (!windowsMjs.includes("height: 40")) {
  failures.push("TITLE_BAR_OVERLAY missing height: 40");
} else if (!windowsMjs.includes("color: \"#00000000\"")) {
  failures.push("TITLE_BAR_OVERLAY missing color: #00000000");
} else if (!windowsMjs.includes("symbolColor: \"#90909d\"")) {
  failures.push("TITLE_BAR_OVERLAY missing symbolColor: #90909d");
}

// Must use titleBarStyle: "hidden" for win32 (not "default")
if (!windowsMjs.includes("process.platform === \"win32\" ? \"hidden\"")) {
  failures.push("Missing titleBarStyle: hidden for win32 in windows.mjs");
}

// Must have autoHideMenuBar for win32
if (!windowsMjs.includes("autoHideMenuBar: true")) {
  failures.push("Missing autoHideMenuBar: true for win32 in windows.mjs");
}

// Must conditionally apply titleBarOverlay only on win32
if (!windowsMjs.match(/\(process\.platform === "win32"\s*\?\s*\{.*titleBarOverlay.*\}/)) {
  failures.push("titleBarOverlay not conditionally applied to win32 in windows.mjs");
}

// 2. Check desktopShell.ts exports isWindowsDesktop
const desktopShell = readFileSync(join(__dirname, "ui/src/lib/desktopShell.ts"), "utf-8");
if (!desktopShell.includes("export function isWindowsDesktop")) {
  failures.push("Missing isWindowsDesktop export in desktopShell.ts");
} else if (!desktopShell.match(/isWindowsDesktop.*win32/)) {
  failures.push("isWindowsDesktop does not check for win32 platform");
}

// 3. Check App.tsx uses isWindowsDesktop to add app--windows class
const appTsx = readFileSync(join(__dirname, "ui/src/App.tsx"), "utf-8");
if (!appTsx.includes("isWindowsDesktop()")) {
  failures.push("App.tsx does not call isWindowsDesktop()");
} else if (!appTsx.includes("app--windows")) {
  failures.push("App.tsx does not add app--windows class");
}

// 4. Check top-strip.css has --wc-inset for Windows
const topStripCss = readFileSync(join(__dirname, "ui/src/styles/top-strip.css"), "utf-8");
if (!topStripCss.includes("--wc-inset")) {
  failures.push("Missing --wc-inset CSS variable in top-strip.css");
} else if (!topStripCss.match(/\.app--windows.*--wc-inset.*138px/)) {
  failures.push(".app--windows does not set --wc-inset to 138px value");
}

// 5. Check loading.js sets data-platform attribute
const loadingJs = readFileSync(join(__dirname, "desktop/pages/loading.js"), "utf-8");
if (!loadingJs.includes("data-platform")) {
  failures.push("loading.js does not set data-platform attribute");
} else if (!loadingJs.match(/dataset\.platform.*api\?\.platform/)) {
  failures.push("loading.js does not use api.platform for data-platform");
}

// 6. Check loading.css shows .drag on both darwin and win32
const loadingCss = readFileSync(join(__dirname, "desktop/pages/loading.css"), "utf-8");
if (!loadingCss.match(/data-platform="darwin"\s+\.drag/)) {
  failures.push("loading.css missing darwin drag strip rule");
} else if (!loadingCss.match(/data-platform="win32"\s+\.drag/)) {
  failures.push("loading.css missing win32 drag strip rule");
}

// 7. Check SidebarTopStrip renders panel-top on Windows even without toggle
const sidebarTopStrip = readFileSync(join(__dirname, "ui/src/components/SidebarTopStrip.tsx"), "utf-8");
if (!sidebarTopStrip.includes("isWindowsDesktop()")) {
  failures.push("SidebarTopStrip does not check isWindowsDesktop()");
} else if (!sidebarTopStrip.match(/onPanelToggle\s*\|\|\s*isWindowsDesktop/)) {
  failures.push("SidebarTopStrip condition for panel-top missing isWindowsDesktop");
}

if (failures.length > 0) {
  console.error("FAILURES:");
  for (const f of failures) console.error("  - " + f);
  process.exit(1);
}

console.log("PASS: All Windows titleBarOverlay integration checks passed");
